def solve(payload):
    events = []
    for line in payload.get('text', '').splitlines():
        fields = line.split(',')
        if len(fields) == 5:
            events.append({'at': int(fields[0]), 'level': fields[1], 'code': fields[2], 'message': fields[3], 'tags': fields[4].split(';') if fields[4] else []})
    counts = {level: sum(event['level'] == level for event in events) for level in ('INFO', 'WARN', 'ERROR')}
    latest = {}
    for event in events: latest[event['code']] = {'at': event['at'], 'level': event['level']}
    return {'events': events, 'counts': counts, 'latest_by_code': latest}

def solve(payload):
    import csv
    rows = list(csv.reader(payload.get('text', '').splitlines()))
    events = []
    for row in rows:
        if len(row) != 5: continue
        events.append({'at': int(row[0]), 'level': row[1], 'code': row[2], 'message': row[3], 'tags': row[4].split(';') if row[4] else []})
    counts = {'INFO': 0, 'WARN': 0, 'ERROR': 0}
    latest = {}
    for event in events:
        counts[event['level']] += 1
        latest[event['code']] = {'at': event['at'], 'level': event['level']}
    return {'events': sorted(events, key=lambda event: event['at']), 'counts': counts, 'latest_by_code': latest}
